// all returns the indexes packaged as a heterogeneous slice for registration
// via gorp.TableConfig.Indexes when opening the underlying table.
func (i indexes) all() []gorp.Index[Key, Schematic] {
	return []gorp.Index[Key, Schematic]{
		i.name,
		i.search,
	}
}

// references returns the references packaged for registration via
// gorp.TableConfig.References when opening the underlying table.
func (i indexes) references() []gorp.Reference[Key, Schematic] {
	return []gorp.Reference[Key, Schematic]{
		i.group,
		i.project,
		i.nodesConfigStateChannel,
		i.nodesConfigCommandChannel,
		i.nodesConfigChannel,
	}
}

// MatchSearch matches the schematics whose text matches term.
// The closest match comes first.
func MatchSearch(term string) Filter {
	return func(r Retrieve) gorp.Filter[Key, Schematic] {
		return r.indexes.search.Filter(term)
	}
}

// Order is a sort that OrderBy applies. An OrderBy function builds one.
type Order func(r Retrieve) gorp.OrderQuery[Key, Schematic]

// OrderBy walks the schematics in the order o defines.
func (r Retrieve) OrderBy(o Order) Retrieve {
	r.gorp = r.gorp.OrderBy(o(r))
	return r
}

// OrderByName returns an Order by name in lower case, then by key.
func OrderByName(dir gorp.Direction) Order {
	return func(r Retrieve) gorp.OrderQuery[Key, Schematic] {
		return r.indexes.name.Ordered(dir)
	}
}

// OrderByNameAfter returns an Order like OrderByName that starts strictly past the
// position of value and key.
func OrderByNameAfter(
	dir gorp.Direction,
	value string,
	key Key,
) Order {
	return func(r Retrieve) gorp.OrderQuery[Key, Schematic] {
		return r.indexes.name.Ordered(dir).After(
			compare.TextKey(string(value)),
			key,
		)
	}
}

// Filter is a per-service filter that is bound to the Retrieve when passed to
// Where. Pure filters ignore the Retrieve argument; service-bound filters read
// from it (e.g. r.indexes, r.label, r.hostProvider) to evaluate. Use Match to
// construct one from a closure.
//
// Filter is a type alias for gorp.BoundFilter[Retrieve, K, E] so the
// composition helpers (Match / And / Or / Not) can be one-line wrappers
// around their gorp.*Bound counterparts instead of re-emitting closure
// plumbing per service.
type Filter = gorp.BoundFilter[Retrieve, Key, Schematic]

// Match wraps a closure that needs the Retrieve into a Filter. The Retrieve
// value is supplied by Retrieve.Where at evaluation time.
func Match(f func(ctx gorp.Context, r Retrieve, e *Schematic) (bool, error)) Filter {
	return gorp.MatchBound[Retrieve, Key, Schematic](f)
}

// And returns a filter that matches when all provided filters match.
func And(fs ...Filter) Filter {
	return gorp.AndBound[Retrieve, Key, Schematic](fs...)
}

// Or returns a filter that matches when any provided filter matches.
func Or(fs ...Filter) Filter {
	return gorp.OrBound[Retrieve, Key, Schematic](fs...)
}

// Not returns a filter that inverts the provided filter.
func Not(f Filter) Filter {
	return gorp.NotBound[Retrieve, Key, Schematic](f)
}

// Search filters the schematics to those whose text matches
// term, closest match first. An empty term adds no filter.
func (r Retrieve) Search(term string) Retrieve {
	if term == "" {
		return r
	}
	return r.Where(MatchSearch(term))
}

// MatchKeys returns a filter that restricts results to
// schematics whose key matches any of the provided
// values. Composing MatchKeys at the top level of a Where clause (i.e.
// r.Where(MatchKeys(...))) dispatches Exec to the multi-get fast path; composing
// inside Or / Not falls back to a full scan.
func MatchKeys(keys ...Key) Filter {
	return func(Retrieve) gorp.Filter[Key, Schematic] {
		return gorp.MatchKeys[Key, Schematic](keys...)
	}
}

// MatchGroups returns a filter for schematics
// whose Group matches any of the provided
// values.
func MatchGroups(vals ...group.Key) Filter {
	return func(r Retrieve) gorp.Filter[Key, Schematic] {
		return r.indexes.group.Filter(vals...)
	}
}

// MatchHasGroup returns a filter for schematics whose
// Group holds a target when has is true, and holds none when has is false.
func MatchHasGroup(has bool) Filter {
	return func(r Retrieve) gorp.Filter[Key, Schematic] {
		return r.indexes.group.FilterHolding(has)
	}
}

// setGroup returns an update that sets the Group of the
// schematics with keys to v.
func setGroup(
	table *gorp.Table[Key, Schematic],
	v *group.Key,
	keys ...Key,
) gorp.Update[Key, Schematic] {
	return table.NewUpdate().
		Where(gorp.MatchKeys[Key, Schematic](keys...)).
		Change(func(_ gorp.Context, e Schematic) Schematic {
			e.Group = v
			return e
		})
}

// MatchProjects returns a filter for schematics
// whose Project matches any of the provided
// values.
func MatchProjects(vals ...project.Key) Filter {
	return func(r Retrieve) gorp.Filter[Key, Schematic] {
		return r.indexes.project.Filter(vals...)
	}
}

// MatchHasProject returns a filter for schematics whose
// Project holds a target when has is true, and holds none when has is false.
func MatchHasProject(has bool) Filter {
	return func(r Retrieve) gorp.Filter[Key, Schematic] {
		return r.indexes.project.FilterHolding(has)
	}
}

// Where applies the provided filter to the query, binding it to the Retrieve
// so service-bound filters can read from r.indexes, r.label, r.hostProvider,
// etc. To compose multiple filters, chain Where calls or pass a combined
// filter via And / Or.
func (r Retrieve) Where(filter Filter) Retrieve {
	r.gorp = r.gorp.Where(filter(r))
	return r
}

// Entry binds the provided schematic as the result container for the
// query. If multiple schematics match, the first one is
// used.
func (r Retrieve) Entry(e *Schematic) Retrieve {
	r.gorp = r.gorp.Entry(e)
	return r
}

// Entries binds the provided slice of schematics as the
// result container for the query.
func (r Retrieve) Entries(es *[]Schematic) Retrieve {
	r.gorp = r.gorp.Entries(es)
	return r
}

// Limit sets the maximum number of schematics to return.
func (r Retrieve) Limit(limit int) Retrieve { r.gorp = r.gorp.Limit(limit); return r }

// After starts the query strictly past key in key order. It panics on a query with an
// OrderBy, since an Order carries its own cursor.
func (r Retrieve) After(key Key) Retrieve {
	r.gorp = r.gorp.After(key)
	return r
}

// SkipMissingKeys makes Exec treat a key with no schematic as a
// non-match instead of returning query.ErrNotFound.
func (r Retrieve) SkipMissingKeys() Retrieve {
	r.gorp = r.gorp.SkipMissingKeys()
	return r
}

// Exec executes the query against snap. It panics when snap is nil.
func (r Retrieve) Exec(ctx context.Context, snap gorp.Snapshot) error {
	return r.gorp.Exec(ctx, snap)
}

// Count returns the number of schematics in snap that match
// the query. It panics when snap is nil.
func (r Retrieve) Count(ctx context.Context, snap gorp.Snapshot) (int, error) {
	return r.gorp.Count(ctx, snap)
}

// Exists checks whether any schematics in snap match the
// query. It panics when snap is nil.
func (r Retrieve) Exists(ctx context.Context, snap gorp.Snapshot) (bool, error) {
	return r.gorp.Exists(ctx, snap)
}
